CREATE TABLE IF NOT EXISTS settlement_workflows (id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL, outcome_json TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settlement_workflow_steps (workflow_id TEXT NOT NULL, step_index INTEGER NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL, tx_hash TEXT, ledger INTEGER, attempts INTEGER NOT NULL DEFAULT 0, compensatable INTEGER NOT NULL, PRIMARY KEY(workflow_id, step_index));
CREATE TABLE IF NOT EXISTS settlement_prices (id TEXT PRIMARY KEY, series_id TEXT NOT NULL UNIQUE, price TEXT NOT NULL, from_ledger INTEGER NOT NULL, to_ledger INTEGER NOT NULL, source TEXT NOT NULL, observations_json TEXT NOT NULL, dispute_deadline_ledger INTEGER NOT NULL, challenged INTEGER NOT NULL DEFAULT 0, finalized_ledger INTEGER);
CREATE TABLE IF NOT EXISTS settlement_disputes (id TEXT PRIMARY KEY, settlement_price_id TEXT NOT NULL, challenger TEXT NOT NULL, evidence TEXT NOT NULL, status TEXT NOT NULL, reviewer TEXT, outcome TEXT, created_at INTEGER NOT NULL, UNIQUE(settlement_price_id, challenger));
CREATE TABLE IF NOT EXISTS chain_storage_keys (key_xdr TEXT PRIMARY KEY, contract_id TEXT NOT NULL, durability TEXT NOT NULL, live_until_ledger INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1, last_bump_ledger INTEGER, extension_ledgers INTEGER, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_chain_storage_keys_contract_ttl ON chain_storage_keys(contract_id, active, live_until_ledger);
